window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ffa78c72453c3fe"]={"versions": [{"id": "FIG-2ffa78c72453c3fe", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-BSW-Konfigurationsparameter (Metamodell-Ausschnitt für <code>ParamConfContainerDef</code> und <code>IntegerParamDef</code>) des Moduls Diagnostic Communication Manager (DCM). Es modelliert die Konfigurationsstruktur des Diagnostic Service Processing Submoduls (DSP) für den OBD-Dienst Service $08 („Request control of on-board system, test or component“) gemäß ISO 15031-5 / SAE J1979 in der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>DcmDsp</code> (<code>ParamConfContainerDef</code>): Übergeordneter Konfigurationscontainer des DSP-Submoduls (Multiplizität: lower = 1, upper = 1).\n</li><li><code>DcmDspRequestControl</code> (<code>ParamConfContainerDef</code>): Über Komposition (<code>+subContainer</code>) an <code>DcmDsp</code> angebundener Konfigurationscontainer für einzelne Service-$08-Steuerungsanforderungen (Multiplizität: lower = 0, upper = *).\n</li><li>Enthaltene Konfigurationsparameter (jeweils über Komposition <code>+parameter</code> an <code>DcmDspRequestControl</code> gebunden, Metatyp <code>IntegerParamDef</code>, Multiplizität lower = 1, upper = 1, Wertebereich min = 0, max = 255):\n<ul class=\"fig-list\"><li><code>DcmDspRequestControlTestId</code>: Identifikator (TID) des auszuführenden Tests bzw. der Steuerungsanforderung.\n</li><li><code>DcmDspRequestControlInBufferSize</code>: Größe des Eingabepuffers in Byte für die Steuerungsanforderung.\n</li><li><code>DcmDspRequestControlOutBufferSize</code>: Größe des Ausgabepuffers in Byte für die Rückmeldedaten der Steuerungsanforderung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell- und Konfigurationsdiagramm ohne Darstellung von Laufzeit- oder Sequenzabläufen. Das Diagramm definiert die Struktur für die BSW-Codegenerierung: Bei Empfang einer OBD-Service-$08-Diagnoseanfrage prüft der DCM anhand von <code>DcmDspRequestControlTestId</code>, ob die angefragte Test-ID konfiguriert ist, und validiert die übertragene Request-Länge anhand von <code>DcmDspRequestControlInBufferSize</code>. Bei gültiger Anforderung wird der zugehörige Software-Ablauf getriggert und der Ausgabepuffer gemäß <code>DcmDspRequestControlOutBufferSize</code> dimensioniert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative BSW-Parameterdefinition für Steuergeräte-Integratoren und DCM-Entwickler:</p>\n<ul class=\"fig-list\"><li><code>DcmDspRequestControl</code> ist optional (Multiplizität 0..*), muss jedoch für jede unterstützte Service-$08-Test-ID konfiguriert werden.\n</li><li>Bei Instanziierung von <code>DcmDspRequestControl</code> sind alle drei Parameter (<code>TestId</code>, <code>InBufferSize</code>, <code>OutBufferSize</code>) Pflichtparameter (Kardinalität 1..1).\n</li><li>Der Wertebereich aller Parameter ist auf 0 bis 255 (8-Bit-Ganzzahl) limitiert; Puffergrößen für Request- und Response-Daten sind damit auf maximal 255 Bytes begrenzt.\n</li><li>Die konfigurierten Puffergrößen müssen konsistent mit den über RTE oder BSW-Schnittstellen bereitgestellten Puffer- und Nachrichtengrößen der ausführenden Anwendungsroutinen übereinstimmen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c807dbadedd0628a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-BSW-Konfigurationsparameter (Metamodell-Ausschnitt für <code>ParamConfContainerDef</code> und <code>IntegerParamDef</code>) des Moduls Diagnostic Communication Manager (DCM). Es modelliert die Konfigurationsstruktur des Diagnostic Service Processing Submoduls (DSP) für den OBD-Dienst Service $08 („Request control of on-board system, test or component“) gemäß ISO 15031-5 / SAE J1979 in der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>DcmDsp</code> (<code>ParamConfContainerDef</code>): Übergeordneter Konfigurationscontainer des DSP-Submoduls (Multiplizität: lower = 1, upper = 1).\n</li><li><code>DcmDspRequestControl</code> (<code>ParamConfContainerDef</code>): Über Komposition (<code>+subContainer</code>) an <code>DcmDsp</code> angebundener Konfigurationscontainer für einzelne Service-$08-Steuerungsanforderungen (Multiplizität: lower = 0, upper = *).\n</li><li>Enthaltene Konfigurationsparameter (jeweils über Komposition <code>+parameter</code> an <code>DcmDspRequestControl</code> gebunden, Metatyp <code>IntegerParamDef</code>, Multiplizität lower = 1, upper = 1, Wertebereich min = 0, max = 255):\n<ul class=\"fig-list\"><li><code>DcmDspRequestControlTestId</code>: Identifikator (TID) des auszuführenden Tests bzw. der Steuerungsanforderung.\n</li><li><code>DcmDspRequestControlInBufferSize</code>: Größe des Eingabepuffers in Byte für die Steuerungsanforderung.\n</li><li><code>DcmDspRequestControlOutBufferSize</code>: Größe des Ausgabepuffers in Byte für die Rückmeldedaten der Steuerungsanforderung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell- und Konfigurationsdiagramm ohne Darstellung von Laufzeit- oder Sequenzabläufen. Das Diagramm definiert die Struktur für die BSW-Codegenerierung: Bei Empfang einer OBD-Service-$08-Diagnoseanfrage prüft der DCM anhand von <code>DcmDspRequestControlTestId</code>, ob die angefragte Test-ID konfiguriert ist, und validiert die übertragene Request-Länge anhand von <code>DcmDspRequestControlInBufferSize</code>. Bei gültiger Anforderung wird der zugehörige Software-Ablauf getriggert und der Ausgabepuffer gemäß <code>DcmDspRequestControlOutBufferSize</code> dimensioniert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative BSW-Parameterdefinition für Steuergeräte-Integratoren und DCM-Entwickler:</p>\n<ul class=\"fig-list\"><li><code>DcmDspRequestControl</code> ist optional (Multiplizität 0..*), muss jedoch für jede unterstützte Service-$08-Test-ID konfiguriert werden.\n</li><li>Bei Instanziierung von <code>DcmDspRequestControl</code> sind alle drei Parameter (<code>TestId</code>, <code>InBufferSize</code>, <code>OutBufferSize</code>) Pflichtparameter (Kardinalität 1..1).\n</li><li>Der Wertebereich aller Parameter ist auf 0 bis 255 (8-Bit-Ganzzahl) limitiert; Puffergrößen für Request- und Response-Daten sind damit auf maximal 255 Bytes begrenzt.\n</li><li>Die konfigurierten Puffergrößen müssen konsistent mit den über RTE oder BSW-Schnittstellen bereitgestellten Puffer- und Nachrichtengrößen der ausführenden Anwendungsroutinen übereinstimmen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2ffa78c72453c3fe", "to": "FIG-c807dbadedd0628a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammrahmen: Der äußere UML-Diagrammrahmen <code>class DcmDspRequestControl</code> wurde entfernt.\n</li><li><code>DcmDsp</code>, <code>DcmDspRequestControl</code>, <code>DcmDspRequestControlTestId</code>, <code>DcmDspRequestControlInBufferSize</code>, <code>DcmDspRequestControlOutBufferSize</code>: Layout der Klassenkästen angepasst (explizite horizontale Trennlinie zwischen Header- und Attributfach eingefügt) sowie Darstellungsreihenfolge der Attribute (<code>lowerMultiplicity</code>, <code>upperMultiplicity</code>, <code>min</code>, <code>max</code>) innerhalb der Fächer umgestellt.\n</li></ul>"}]};
